// Hand-written `rxjs` stub: the subject a stream service fans out through, and
// the operators a screen narrows it with.

export interface Subscription {
  unsubscribe(): void;
}

export type OperatorFunction<T, R> = (source: Observable<T>) => Observable<R>;

export declare class Observable<T> {
  subscribe(next?: (value: T) => void): Subscription;
  pipe(): Observable<T>;
  pipe<A>(op1: OperatorFunction<T, A>): Observable<A>;
  pipe<A, B>(op1: OperatorFunction<T, A>, op2: OperatorFunction<A, B>): Observable<B>;
}

export declare class Subject<T> extends Observable<T> {
  next(value: T): void;
  complete(): void;
  asObservable(): Observable<T>;
}

export declare function filter<T>(predicate: (value: T) => boolean): OperatorFunction<T, T>;
export declare function takeUntil<T>(notifier: Observable<unknown>): OperatorFunction<T, T>;
